// Package dump deeply pretty-prints arbitrary Go values for inspection.
package dump

import (
	"io"

	"github.com/davecgh/go-spew/spew"
)

// config is tuned for debugging: sorted map keys for stable output,
// pointer addresses hidden so diffs between runs stay readable, and
// Stringer/error methods bypassed so the raw structure is always shown.
var config = spew.ConfigState{
	Indent:                  "  ",
	SortKeys:                true,
	DisablePointerAddresses: true,
	DisableMethods:          true,
	SpewKeys:                true,
}

// Sdump returns a deep, human-readable representation of the values.
func Sdump(values ...any) string { return config.Sdump(values...) }

// Fdump writes a deep, human-readable representation of the values to w.
func Fdump(w io.Writer, values ...any) { config.Fdump(w, values...) }
EOF
cat > dump/dump_test.go <<'EOF'
package dump

import (
	"strings"
	"testing"
)

type node struct {
	Name     string
	Tags     map[string]int
	Children []*node
	Parent   *node
	secret   bool
}

func TestSdumpNestedAndCyclic(t *testing.T) {
	root := &node{Name: "root", Tags: map[string]int{"b": 2, "a": 1}}
	child := &node{Name: "child", Parent: root, secret: true}
	root.Children = append(root.Children, child)

	out := Sdump(root)
	for _, want := range []string{`"root"`, `"child"`, "already shown", "secret: (bool) true"} {
		if !strings.Contains(out, want) {
			t.Errorf("output missing %q:\n%s", want, out)
		}
	}
	if strings.Index(out, `"a"`) > strings.Index(out, `"b"`) {
		t.Errorf("map keys not sorted:\n%s", out)
	}
}
EOF
cat > cmd/debugdump/main.go <<'EOF'
// Command debugdump demonstrates the dump package on a sample structure.
package main

import (
	"os"

	"debugdump/dump"
)

type item struct {
	ID    int
	Attrs map[string]any
	Next  *item
}

func main() {
	a := &item{ID: 1, Attrs: map[string]any{"color": "red", "sizes": []int{1, 2, 3}}}
	b := &item{ID: 2, Next: a}
	a.Next = b // cycle
	dump.Fdump(os.Stdout, a)
}
EOF
